mapper.update:
UPDATE PM_PROJECT_MEMBER
SET PROJECT_ROLE = 'MANAGER',
    ACTIVE_YN = 'Y',
    UPDATED_AT = SYSTIMESTAMP,
    UPDATED_BY = #{ownerUsername}
WHERE PROJECT_ID = #{projectId}
  AND USERNAME <> #{ownerUsername}
  AND PROJECT_ROLE = 'OWNER'

UPDATE PM_PROJECT_MEMBER
SET PROJECT_ROLE = #{member.role},
    ACTIVE_YN = 'Y''N',
    UPDATED_AT = SYSTIMESTAMP,
    UPDATED_BY = #{member.username}
WHERE PROJECT_ID = #{member.projectId}
  AND USERNAME = #{member.username}

mapper.delete:
DELETE FROM PM_PROJECT_MEMBER
WHERE PROJECT_ID = #{projectId}
  AND USERNAME = #{username}

mapper.select:
SELECT NVL(MAX(SEQUENCE_NO), 0) + 1
FROM PM_PROJECT_STATUS_HISTORY
WHERE PROJECT_ID = #{projectId}
